assert len(HUMAN_TEMPLATES) == 25, f"need 25 human templates, got {len(HUMAN_TEMPLATES)}"
assert len(LLM_TEMPLATES) == 25, f"need 25 LLM templates, got {len(LLM_TEMPLATES)}"


def main() -> None:
    ap = argparse.ArgumentParser()
    ap.add_argument(
        "--out",
        default=Path("tests/fixtures/raid_mini.jsonl"),
        type=Path,
    )
    ap.add_argument("--seed", type=int, default=42)
    args = ap.parse_args()

    # Quick sanity check: every template must clear the 50-word floor that the
    # cascade enforces, otherwise the smoke run will silently skip them.
    for i, t in enumerate(HUMAN_TEMPLATES):
        wc = len(t.split())
        assert wc >= 50, f"human template {i} only {wc} words"
    for i, t in enumerate(LLM_TEMPLATES):
        wc = len(t.split())
        assert wc >= 50, f"LLM template {i} only {wc} words"

    rng = random.Random(args.seed)
    rows = []
    for i, text in enumerate(HUMAN_TEMPLATES):
        rows.append({
            "id": f"raid_synth_human_{i:03d}",
            "text": text,
            "label": 0,
            "source": "synthetic_placeholder",
            "attack_name": None,
            "tier": "raid",
        })
    for i, text in enumerate(LLM_TEMPLATES):
        rows.append({
            "id": f"raid_synth_llm_{i:03d}",
            "text": text,
            "label": 1,
            "source": "synthetic_placeholder",
            "attack_name": None,
            "tier": "raid",
        })
    # Shuffle deterministically so the JSONL is not trivially sorted by label.
    rng.shuffle(rows)

    args.out.parent.mkdir(parents=True, exist_ok=True)
    with args.out.open("w", encoding="utf-8") as f:
        for r in rows:
            f.write(json.dumps(r, ensure_ascii=False) + "\n")
    print(f"wrote {len(rows)} synthetic placeholder rows to {args.out}")


if __name__ == "__main__":
    main()
